import json
from pathlib import Path

def load_config(config_path):
    """Load config from JSON or YAML file."""
    ext = Path(config_path).suffix.lower()
    if ext == '.json':
        with open(config_path, 'r', encoding='utf-8') as f:
            return json.load(f)
    elif ext in ('.yaml', '.yml'):
        with open(config_path, 'r', encoding='utf-8') as f:
            return parse_yaml(f.read())
    else:
        raise ValueError(f'Unsupported config format: {ext}')

def parse_yaml(text):
    """Simple YAML parser for flat key-value pairs (no nesting)."""
    result = {}
    for line in text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if ':' in line:
            key, val = line.split(':', 1)
            key = key.strip()
            val = val.strip()
            # Handle quoted strings
            if val.startswith('"') and val.endswith('"'):
                val = val[1:-1]
            elif val.startswith("'") and val.endswith("'"):
                val = val[1:-1]
            # Try to parse int/float
            try:
                val = int(val)
            except ValueError:
                try:
                    val = float(val)
                except ValueError:
                    pass
            result[key] = val
    return result

import json
from pathlib import Path
from mini_harness.run import get_project_root, run_pipeline


def generate_review_report(output_path='review_report.json'):
    """Generate a memory-aware review report."""
    root = get_project_root()

    # Read memory summary
    memory_path = root / 'memory' / 'memory_summary.md'
    if memory_path.exists():
        with open(memory_path, 'r', encoding='utf-8') as f:
            memory_content = f.read()
    else:
        memory_content = 'memory/memory_summary.md not found'

    # Read compatibility notes
    compat_path = root / 'docs' / 'compatibility-notes.md'
    if compat_path.exists():
        with open(compat_path, 'r', encoding='utf-8') as f:
            compat_content = f.read()
    else:
        compat_content = 'docs/compatibility-notes.md not found'

    # Read perf baseline
    perf_path = root / 'benchmarks' / 'perf-baseline.json'
    if perf_path.exists():
        with open(perf_path, 'r', encoding='utf-8') as f:
            perf_content = json.load(f)
    else:
        perf_content = 'benchmarks/perf-baseline.json not found'

    # Run current pipeline on sample data to get stats
    input_csv = root / 'data' / 'input.csv'
    temp_output = root / 'tmp_review_run.json'
    if input_csv.exists():
        try:
            pipeline_result = run_pipeline(str(input_csv), str(temp_output))
            # Clean up temp file
            if temp_output.exists():
                temp_output.unlink()
        except Exception as e:
            pipeline_result = {"error": str(e)}
    else:
        pipeline_result = {"error": "data/input.csv not found"}

    # Build review report
    review = {
        "design_decisions": memory_content,
        "compatibility_notes": compat_content,
        "performance_baseline": perf_content,
        "current_pipeline_stats": pipeline_result,
        "review_timestamp": None  # could add datetime but avoid imports
    }

    with open(output_path, 'w', encoding='utf-8') as f:
        json.dump(review, f, indent=2, ensure_ascii=False)

    return review

import csv
import json
import logging
import re
from pathlib import Path

logging.basicConfig(level=logging.INFO, format='%(asctime)s [%(levelname)s] %(message)s')
logger = logging.getLogger(__name__)

_PROJECT_ROOT = None

def get_project_root():
    global _PROJECT_ROOT
    if _PROJECT_ROOT is None:
        # Traverse upward from cwd looking for src/mini_harness
        path = Path.cwd().resolve()
        for parent in [path] + list(path.parents):
            if (parent / 'src' / 'mini_harness').is_dir():
                _PROJECT_ROOT = parent
                break
        if _PROJECT_ROOT is None:
            # Fallback: traverse from this file's location
            path = Path(__file__).resolve().parent
            for parent in [path] + list(path.parents):
                if (parent / 'src' / 'mini_harness').is_dir():
                    _PROJECT_ROOT = parent
                    break
        if _PROJECT_ROOT is None:
            _PROJECT_ROOT = Path.cwd()
    return _PROJECT_ROOT


def to_snake_case(name):
    s1 = re.sub(r'(.)([A-Z][a-z]+)', r'\1_\2', name)
    s2 = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', s1)
    return re.sub(r'[^a-zA-Z0-9]', '_', s2).lower()


def extract(input_path):
    """Read CSV or JSONL, return list of dicts."""
    records = []
    ext = Path(input_path).suffix.lower()
    if ext == '.csv':
        with open(input_path, newline='', encoding='utf-8') as f:
            lines = [line for line in f if not line.startswith('#')]
            reader = csv.DictReader(lines)
            for row in reader:
                records.append(row)
    elif ext == '.jsonl':
        with open(input_path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if line:
                    records.append(json.loads(line))
    else:
        raise ValueError(f'Unsupported file format: {ext}')
    return records


def clean(records):
    """Remove empty rows, convert field names to snake_case, separate rejects."""
    cleaned = []
    rejects = []
    for rec in records:
        if not rec or all(v is None or (isinstance(v, str) and v.strip() == '') for v in rec.values()):
            continue
        new_rec = {}
        for k, v in rec.items():
            new_key = to_snake_case(k)
            new_rec[new_key] = v
        if 'id' not in new_rec or new_rec['id'] is None or (isinstance(new_rec['id'], str) and new_rec['id'].strip() == ''):
            rejects.append(new_rec)
        else:
            cleaned.append(new_rec)
    return cleaned, rejects


def build_report(cleaned_count, rejected_count, retry_count, source_files):
    """Return report dict with required fields."""
    report = {
        'processed_count': cleaned_count,
        'rejected_count': rejected_count,
        'retry_count': retry_count,
        'source_files': source_files
    }
    memory_path = get_project_root() / 'memory' / 'memory_summary.md'
    if memory_path.exists():
        with open(memory_path, 'r', encoding='utf-8') as mf:
            report['memory_summary'] = mf.read()
    else:
        report['memory_summary'] = 'memory/memory_summary.md not found'
    return report


def resolve_path(path_str):
    """Resolve path: if not absolute and doesn't exist, try relative to project root."""
    p = Path(path_str)
    if p.is_absolute():
        return str(p.resolve())
    # First try as relative to cwd
    if p.exists():
        return str(p.resolve())
    # Then try relative to project root
    candidate = get_project_root() / p
    if candidate.exists():
        return str(candidate.resolve())
    # Fallback: return resolved cwd relative (will likely fail later)
    return str(p.resolve())


def run_pipeline(input_path, output_path):
    """Execute DAG: extract -> clean -> report, with up to 2 retries."""
    resolved_input = resolve_path(input_path)
    max_retries = 2
    result = None

    for attempt in range(1, max_retries + 1):
        retry_count = attempt - 1
        logger.info(f'attempt={attempt}, stage=extract, status=start')
        try:
            records = extract(resolved_input)
        except Exception as e:
            logger.error(f'attempt={attempt}, stage=extract, status=failed, error={e}')
            if attempt == max_retries:
                raise
            continue

        logger.info(f'attempt={attempt}, stage=clean, status=start')
        try:
            cleaned, rejects = clean(records)
        except Exception as e:
            logger.error(f'attempt={attempt}, stage=clean, status=failed, error={e}')
            if attempt == max_retries:
                raise
            continue

        logger.info(f'attempt={attempt}, stage=report, status=start')
        try:
            report = build_report(len(cleaned), len(rejects), retry_count, [resolved_input])
            with open(output_path, 'w', encoding='utf-8') as f:
                json.dump(report, f, indent=2)
            logger.info(f'attempt={attempt}, stage=report, status=completed')
            result = report
            break
        except Exception as e:
            logger.error(f'attempt={attempt}, stage=report, status=failed, error={e}')
            if attempt == max_retries:
                raise
            continue

    if result is None:
        raise RuntimeError('Pipeline failed after max retries')
    return result

